use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn lowest_common_ancestor(r:Option<Rc<RefCell<TreeNode>>>,p:Option<Rc<RefCell<TreeNode>>>,q:Option<Rc<RefCell<TreeNode>>>)->Option<Rc<RefCell<TreeNode>>>{fn f(r:&Option<Rc<RefCell<TreeNode>>>,pv:i32,qv:i32)->Option<Rc<RefCell<TreeNode>>>{if let Some(x)=r{let b=x.borrow();if b.val==pv||b.val==qv{return Some(x.clone())}let l=f(&b.left,pv,qv);let rr=f(&b.right,pv,qv);if l.is_some()&&rr.is_some(){Some(x.clone())}else if l.is_some(){l}else{rr}}else{None}}let pv=p.unwrap().borrow().val;let qv=q.unwrap().borrow().val;f(&r,pv,qv)}}
